from html.parser import HTMLParser
from pathlib import Path
class Page(HTMLParser):
    def __init__(self):
        super().__init__(); self.buttons=[]; self.selects=0; self.options=0; self.radios=0; self.scripts=[]; self.external=[]; self.in_script=False
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if tag=='button': self.buttons.append(a)
        if tag=='select': self.selects+=1
        if tag=='option': self.options+=1
        if tag=='input' and a.get('type')=='radio': self.radios+=1
        if tag=='script':
            self.in_script=True
            if a.get('src'): self.external.append(a['src'])
        if tag in {'link','iframe'} and (a.get('href') or a.get('src')): self.external.append(a.get('href') or a.get('src'))
    def handle_endtag(self, tag):
        if tag=='script': self.in_script=False
    def handle_data(self, data):
        if self.in_script: self.scripts.append(data)
p=Path('prototypes/throwaway-retry.html'); assert p.is_file()
text=p.read_text(); page=Page(); page.feed(text)
active=[b for b in page.buttons if 'disabled' not in b]
assert len(active)>=2, 'Need actionable confirmation controls'
assert (page.selects and page.options>=2) or page.radios>=2 or len(active)>=3, 'Need a variant switching control'
assert not page.external, 'The prototype must run without external assets'
script='\n'.join(page.scripts)
assert script.strip(), 'Static pictures do not exercise the interaction'
assert any(k in text for k in ['addEventListener','onclick','onchange','onsubmit']), 'Controls need event handling'
assert any(k in script for k in ['textContent','innerHTML','hidden','classList','setAttribute','style.']), 'Show interaction state'
assert not any(k in script for k in ['fetch(', 'XMLHttpRequest', 'WebSocket(', 'sendBeacon(']), 'Real mutations are out of scope'
